import React, { useState } from "react";
import birthdayConfig from "./config/birthdayConfig";
import memories from "./data/memories";

import ParticleBackground from "./components/ParticleBackground";
import CustomCursor from "./components/CustomCursor";
import SectionIndicator from "./components/SectionIndicator";
import Intro from "./components/Intro";
import BirthdayHero from "./components/BirthdayHero";
import MemoryGallery from "./components/MemoryGallery";
import QuoteSection from "./components/QuoteSection";
import PersonalMessage from "./components/PersonalMessage";
import FinalSection from "./components/FinalSection";
import MusicPlayer from "./components/MusicPlayer";

import "./App.css";

const sections = [
  { id: "birthday-reveal", label: "Reveal" },
  { id: "memories", label: "Memories" },
  { id: "quote", label: "Reflection" },
  { id: "personal-message", label: "Letter" },
  { id: "final", label: "Celebration" },
];

function App() {
  const [isOpened, setIsOpened] = useState(false);
  const [musicTrigger, setMusicTrigger] = useState(false);

  const handleOpen = () => {
    // 1. Trigger audio playback safely on user click
    setMusicTrigger(true);
    // 2. Mark opened state
    setIsOpened(true);

    // 3. Smooth scroll down to the Birthday Hero reveal
    setTimeout(() => {
      const hero = document.getElementById("birthday-reveal");
      if (hero) {
        hero.scrollIntoView({ behavior: "smooth" });
      }
    }, 450);
  };

  const handleReplay = () => {
    const hero = document.getElementById("birthday-reveal");
    if (hero) {
      hero.scrollIntoView({ behavior: "smooth" });
    }
  };

  return (
    <div className="app-container">
      {/* Subtle organic noise texture overlay */}
      <div className="noise-overlay" aria-hidden="true" />

      {/* Ambient particle & radial lighting canvas */}
      <ParticleBackground />

      {/* Desktop subtle cursor glow follower */}
      <CustomCursor />

      {/* Intro Entrance Screen (unmounts/slides out on open) */}
      <Intro config={birthdayConfig} onOpen={handleOpen} isOpened={isOpened} />

      {/* Section Indicator dots & numbers (visible once opened) */}
      {isOpened && <SectionIndicator sections={sections} />}

      {/* Main Experience Stream */}
      <main id="experience-main" className="experience-main">
        {/* Section 01: Birthday Reveal */}
        <BirthdayHero config={birthdayConfig} isOpened={isOpened} />

        {/* Section 02: Memory Journey (Continuous horizontal photo stream) */}
        <MemoryGallery config={birthdayConfig} memories={memories} />

        {/* Section 03: Cinematic Quote Break */}
        <QuoteSection config={birthdayConfig} />

        {/* Section 04: Personal Heartfelt Message */}
        <PersonalMessage config={birthdayConfig} />

        {/* Section 05: Grand Final Celebration & Confetti */}
        <FinalSection config={birthdayConfig} onReplay={handleReplay} />
      </main>

      {/* Bottom-right audio controller */}
      <MusicPlayer
        audioSrc={birthdayConfig.music?.audioSrc}
        autoStartTrigger={musicTrigger}
      />
    </div>
  );
}

export default App;
